window.bookSummaryJSON = "<b>#1 <i>New York Times</i> bestselling author J.R. Ward’s <i>The Wedding From Hell </i>is an exclusive three-part bind-up prequel to her upcoming standalone suspense novel <i>Consumed </i>and takes us back to where it all started between arson investigator Anne Ashburn and ‘bad boy’ firefighter Danny Maguire. <i>The Wedding From Hell</i> is a sexy standalone novel that sets up C<i>onsumed</i>’s storyline, leaving fans hungry for more and dying to snatch it up.</b>"; 
